using System.Globalization;
using System.Text.Json;
using Microsoft.EntityFrameworkCore;
using Shop.SharedKernel;
namespace Shop.Modules.Credit;
public sealed class CreditReviewService(CreditDbContext db,CreditRequirementsService requirements,CreditSubmissionService submissions,IPrivateFileVault vault,ICreditApplicationProtection protection,TimeProvider clock)
{
    private static readonly JsonSerializerOptions Json=CreditRequirementsRules.Json;
    public async Task<CreditReviewCapabilities> CapabilitiesAsync(string actor,bool writer,string applicationId,CancellationToken ct)
    {
        var app=await Visible(actor,true,applicationId,false,ct);var blockers=new List<string>();if(!writer)blockers.Add("credit_review_write_required");if(app.State!="Submitted")blockers.Add("credit_application_not_submitted");if(await db.ApplicationReviews.CountAsync(x=>x.ApplicationId==app.Id,ct)>=20)blockers.Add("credit_review_capacity");var approval=new List<string>();if(app.State=="Submitted"){if(app.CurrentSubmissionId is null||app.CurrentReviewId is not null)throw CreditApplicationRules.Unavailable();var snapshot=await submissions.DetailAsync(actor,true,app.Id,app.CurrentSubmissionId,ct);if(snapshot.Documents.Length>0&&!vault.Configured)approval.Add("private_file_unavailable");}return new(1,CreditApplicationService.Summary(app),app.CurrentSubmissionId,blockers.Count==0,blockers.Count==0&&approval.Count==0,blockers.ToArray(),approval.ToArray());
    }
    public async Task<CreditReviewResult> ReviewAsync(string actor,string applicationId,string commandId,ReviewCreditApplicationInput input,CancellationToken ct)
    {
        actor=CreditApplicationRules.Actor(actor);CreditApplicationRules.Id(commandId);input=CreditReviewRules.Validate(input);CreditApplicationRules.Id(applicationId);var hash=CreditApplicationRules.Hash(JsonSerializer.Serialize(new{ApplicationId=applicationId,Input=input},Json));await requirements.LockAsync("sayman:credit:requirements:v1",ct);await requirements.LockAsync("sayman:credit:application-commands:v1",ct);var app=await Visible(actor,true,applicationId,true,ct);var previous=await db.ReviewCommands.AsNoTracking().SingleOrDefaultAsync(x=>x.ActorId==actor&&x.CommandId==commandId,ct);if(previous is not null){if(previous.ApplicationId!=applicationId||previous.PayloadHash!=hash)throw new BusinessException("credit_review_idempotency_conflict","This review command has different input.");return Receipt(previous)with{Replayed=true};}
        if(app.State!="Submitted"||app.CurrentSubmissionId!=input.SubmissionId||app.CurrentReviewId is not null||Convert.ToBase64String(app.Version)!=input.ApplicationVersion||await db.ApplicationReviews.CountAsync(x=>x.ApplicationId==app.Id,ct)>=20)throw CreditReviewRules.Conflict();var snapshot=await submissions.DetailAsync(actor,true,app.Id,input.SubmissionId,ct);var now=clock.GetUtcNow().ToUniversalTime();if(now<app.ChangedAt)now=app.ChangedAt;long? amount=input.ApprovedAmountRial is{}money?CreditApplicationRules.Amount(money):null;if(!CreditReviewRules.ValidApproval(input.Outcome,amount,input.ExpiresAt,now)||amount>app.RequestedAmountRial)throw CreditReviewRules.Invalid();if(input.Outcome=="Approved"&&snapshot.Documents.Length>0&&!vault.Configured)throw new BusinessException("private_file_unavailable","Secure document access must be configured before approving this submission.");
        var row=new CreditApplicationReview{ApplicationId=app.Id,SubmissionId=input.SubmissionId,Outcome=input.Outcome,Locale=input.Locale,ApprovedAmountRial=amount,ExpiresAt=input.ExpiresAt,ActorId=actor,At=now};var note=JsonSerializer.Serialize(input.Note,Json);row.NoteHash=CreditApplicationRules.Hash(note);row.ProtectedNote=protection.Protect(app.Id,"review-note",row.Id,note);db.ApplicationReviews.Add(row);app.State=input.Outcome=="Returned"?"Draft":input.Outcome;app.CurrentReviewId=row.Id;app.ChangedAt=now;db.ApplicationEvents.Add(new(){ApplicationId=app.Id,ActorId=actor,Action=input.Outcome,At=now});await db.SaveChangesAsync(ct);var result=new CreditReviewResult(1,false,commandId,CreditApplicationService.Summary(app),Summary(row),input.Note);var raw=JsonSerializer.Serialize(result,Json);db.ReviewCommands.Add(new(){ActorId=actor,CommandId=commandId,ApplicationId=app.Id,ReviewId=row.Id,PayloadHash=hash,ResultHash=CreditApplicationRules.Hash(raw),ProtectedResult=protection.Protect(app.Id,"review-receipt",CreditApplicationRules.Hash(actor+":"+commandId),raw),At=now});await db.SaveChangesAsync(ct);return result;
    }
    public async Task<CreditReviewResult> ReceiptAsync(string actor,string applicationId,string commandId,CancellationToken ct){actor=CreditApplicationRules.Actor(actor);CreditApplicationRules.Id(commandId);await Visible(actor,true,applicationId,false,ct);var row=await db.ReviewCommands.AsNoTracking().SingleOrDefaultAsync(x=>x.ActorId==actor&&x.ApplicationId==applicationId&&x.CommandId==commandId,ct)??throw CreditApplicationRules.Missing();return Receipt(row)with{Replayed=true};}
    public async Task<CreditReviewPage> PageAsync(string actor,bool staff,string applicationId,CancellationToken ct){await Visible(actor,staff,applicationId,false,ct);var rows=await db.ApplicationReviews.AsNoTracking().Where(x=>x.ApplicationId==applicationId).OrderByDescending(x=>x.Sequence).Take(21).ToArrayAsync(ct);if(rows.Length>20)throw CreditApplicationRules.Unavailable();return new(1,applicationId,rows.Select(Summary).ToArray(),null);}
    public async Task<CreditReviewDetail> DetailAsync(string actor,bool staff,string applicationId,string reviewId,CancellationToken ct){var app=await Visible(actor,staff,applicationId,false,ct);CreditApplicationRules.Id(reviewId);var row=await db.ApplicationReviews.AsNoTracking().SingleOrDefaultAsync(x=>x.Id==reviewId&&x.ApplicationId==applicationId,ct)??throw CreditApplicationRules.Missing();if(row.ApprovedAmountRial>app.RequestedAmountRial)throw CreditApplicationRules.Unavailable();return new(1,CreditApplicationService.Summary(app),Summary(row),ReadNote(row));}
    private async Task<CreditApplication> Visible(string actor,bool staff,string id,bool tracking,CancellationToken ct){actor=CreditApplicationRules.Actor(actor);CreditApplicationRules.Id(id);var query=tracking?db.Applications.AsQueryable():db.Applications.AsNoTracking();return await query.SingleOrDefaultAsync(x=>x.Id==id&&(staff||x.OwnerId==actor),ct)??throw CreditApplicationRules.Missing();}
    private static CreditReviewData Summary(CreditApplicationReview x){CreditApplicationRules.Id(x.Id);CreditApplicationRules.Id(x.SubmissionId);CreditReviewRules.Outcome(x.Outcome);CreditApplicationRules.Locale(x.Locale);if(x.At.Offset!=TimeSpan.Zero||!CreditReviewRules.ValidApproval(x.Outcome,x.ApprovedAmountRial,x.ExpiresAt,x.At))throw CreditApplicationRules.Unavailable();return new(x.Id,x.SubmissionId,x.Outcome,x.Locale,x.ApprovedAmountRial?.ToString(CultureInfo.InvariantCulture),x.ExpiresAt,x.At);}
    private string ReadNote(CreditApplicationReview row){try{var raw=protection.Unprotect(row.ApplicationId,"review-note",row.Id,row.ProtectedNote);if(CreditApplicationRules.Hash(raw)!=row.NoteHash)throw CreditApplicationRules.Unavailable();return CreditReviewRules.Note(JsonSerializer.Deserialize<string>(raw,Json)??throw CreditApplicationRules.Unavailable());}catch(Exception e)when(e is JsonException or BusinessException){throw CreditApplicationRules.Unavailable();}}
    private CreditReviewResult Receipt(CreditReviewCommand row){try{var raw=protection.Unprotect(row.ApplicationId,"review-receipt",CreditApplicationRules.Hash(row.ActorId+":"+row.CommandId),row.ProtectedResult);if(CreditApplicationRules.Hash(raw)!=row.ResultHash)throw CreditApplicationRules.Unavailable();var value=JsonSerializer.Deserialize<CreditReviewResult>(raw,Json)??throw CreditApplicationRules.Unavailable();var expected=value.Review.Outcome=="Returned"?"Draft":CreditReviewRules.Outcome(value.Review.Outcome);if(value.SchemaVersion!=1||value.Replayed||value.CommandId!=row.CommandId||value.Application.Id!=row.ApplicationId||value.Application.State!=expected||value.Review.Id!=row.ReviewId||value.Application.ChangedAt!=value.Review.At)throw CreditApplicationRules.Unavailable();CreditReviewRules.Note(value.Note);return value;}catch(JsonException){throw CreditApplicationRules.Unavailable();}}
}
